import {codeContext} from './code-context.js?v=workbench-1';

// Return the positions of a matching curly-brace pair near the caret.
// Only code is searched: strings, character literals and comments are masked.
export function matchingCurlyBraces(source,caret,language='java',selectionEnd=caret){
 if(typeof source!=='string'||!Number.isInteger(caret)||caret<0||caret>source.length||selectionEnd!==caret)return null;
 const mask=codeContext(source,language).mask;
 // Prefer the brace immediately before the caret (including auto-inserted "{}").
 const at=[caret-1,caret].find(index=>mask[index]==='{'||mask[index]==='}');
 if(at===undefined)return null;
 let depth=0;
 if(mask[at]==='{'){
  for(let i=at;i<mask.length;i++){
   if(mask[i]==='{')depth++;
   else if(mask[i]==='}'&&--depth===0)return{open:at,close:i};
  }
 }else{
  for(let i=at;i>=0;i--){
   if(mask[i]==='}')depth++;
   else if(mask[i]==='{'&&--depth===0)return{open:i,close:at};
  }
 }
 return null;
}

import {codeContext} from './code-context.js?v=workbench-1';
const pairs={'(':')','[':']','{':'}','<':'>'};
const genericTypes=/\b(?:[A-Z][\w$]*|(?:std::)?(?:vector|array|map|unordered_map|multimap|set|unordered_set|multiset|pair|tuple|optional|variant|function|deque|queue|stack|priority_queue|list|forward_list|shared_ptr|unique_ptr|weak_ptr|numeric_limits|bitset|string_view|span|less|greater))$/;
export function bracketEdit(value,start,end,key,language='java'){
 const context=codeContext(value.slice(0,start),language);if(!context.codeAtEnd)return null;
 const next=value[start],selected=value.slice(start,end),angle=key==='<'||key==='>';
 const genericAt=at=>at>=0&&['java','cpp'].includes(language)&&genericTypes.test(value.slice(0,at).trimEnd())&&!/\s$/.test(value.slice(0,at));
 if(key==='Backspace'){
  if(start!==end||!start)return null;const before=value[start-1];if(pairs[before]===next&&(before!=='<'||genericAt(start-1)))return{value:value.slice(0,start-1)+value.slice(end+1),start:start-1,end:start-1};return null;
 }
 if(pairs[key]){
  if(angle&&!genericAt(start))return null;
  if(!selected&&next&&!/[\s\])};,>]/.test(next))return null;
  return{value:value.slice(0,start)+key+selected+pairs[key]+value.slice(end),start:start+1,end:selected?end+1:start+1};
 }
 if(')]}>'.includes(key)&&start===end&&next===key){
  if(key==='>'&&!genericAt(context.mask.lastIndexOf('<')))return null;
  return{value,start:start+1,end:start+1};
 }
 return null;
}

// Signed-in Submit goes through the verified judge for every supported language.
// Guest Java and unavailable private Java judging retain a clearly labeled
// browser-only practice path; they must never masquerade as verified results.
export function usesRemoteSubmit(language, signedIn, submitting) {
  return Boolean(submitting && signedIn && ['java','python','c','cpp'].includes(language));
}
export function privateJavaJudgeUnavailable(error) {
  const message = String(error?.message ?? error ?? '');
  return /requires a configured private Java judge|private Java judging is not connected yet|the private suite is unavailable/i.test(message);
}
export function browserSubmissionCases(problem, customCases = []) {
  if (!Array.isArray(problem?.tests) || !Array.isArray(customCases)) throw new Error('Invalid practice cases.');
  return [...problem.tests, ...customCases];
}
export function browserSubmissionVerdict(problem, passed, total, customCount = 0) {
  const accepted = Number.isInteger(passed) && Number.isInteger(total) && total > 0 && passed === total;
  const hiddenSkipped = Number(problem?.hiddenCount) > 0;
  return {
    accepted, status: accepted ? 'practice_accepted' : 'wrong_answer',
    passed, total, verified: false,
    message: accepted
      ? 'All '+total+' browser test cases passed'+(customCount ? ' (including '+customCount+' custom)' : '')+'. Your progress counts as a practice solve.'+
        (hiddenSkipped ? ' Hidden cases were not checked.' : '')+
        ' No verified server submission or shared-solution benchmark was recorded.'
      : passed+' / '+total+' browser test cases passed. Fix the failed cases and submit again.'
  };
}

import {validateProblem} from './catalog.js?v=structural-2';
import {JavaJudge,buildTests} from './judge.js?v=structural-2';
export function mountBulkImport({cloud,notify,onChanged}){
 const panel=document.getElementById('bulkImport');let stopped=false,running=false,judge;
 document.getElementById('bulkStop').onclick=()=>{stopped=true;judge?.stop();};
 document.getElementById('bulkRun').onclick=async()=>{
  if(running||!cloud.canCreate)return;const output=document.getElementById('bulkStatus'),file=document.getElementById('bulkFile').files[0];
  try{
   if(!file||file.size>25000000)throw new Error('Choose a JSON problem pack under 25 MB.');
   const input=JSON.parse(await file.text());if(!Array.isArray(input)||!input.length||input.length>500)throw new Error('A pack must be an array of 1–500 original or licensed problem definitions.');
   const seen=new Set(),pack=input.map(row=>{const problem=validateProblem(row.problem||row),hiddenTests=row.hiddenTests||[];if(seen.has(problem.id))throw new Error('Duplicate ID: '+problem.id);seen.add(problem.id);if(!Array.isArray(hiddenTests)||hiddenTests.length>100)throw new Error('Invalid hidden cases: '+problem.id);buildTests(problem,hiddenTests);return {problem,hiddenTests};});
   const existing=new Set((await cloud.adminCatalog()).map(p=>p.id));for(const {problem} of pack)if(existing.has(problem.id))throw new Error('ID already exists: '+problem.id+'. Use the editor for corrections.');
   const owner=cloud.user.id,published=document.getElementById('bulkPublished').checked;running=true;stopped=false;document.getElementById('bulkRun').disabled=true;document.getElementById('bulkStop').hidden=false;let saved=0;
   judge=new JavaJudge(status=>{output.textContent=(saved+1)+' / '+pack.length+' · '+status;});
   for(const {problem,hiddenTests} of pack){
    if(stopped||cloud.user?.id!==owner)break;
    const timeout=setTimeout(()=>{stopped=true;judge.stop();},120000);
    let result;try{result=await judge.run(problem.reference,problem,[...problem.tests,...hiddenTests]);}finally{clearTimeout(timeout);}
    if(stopped||cloud.user?.id!==owner)break;
    if(result.status!=='ok'||result.cases.some(c=>!c.passed))throw new Error('Validation failed for '+problem.title+'. '+saved+' earlier problems were saved; this one was not.');
    await cloud.saveProblem(problem,{published,position:existing.size+saved,revision:0,hiddenTests});saved++;
    output.textContent=saved+' / '+pack.length+' verified and saved · '+problem.title;
   }
   output.textContent=(stopped?'Stopped. ':'Complete. ')+saved+' / '+pack.length+' verified problems saved. Earlier saves are retained.';
   await onChanged();notify(saved+' validated problems added.');
  }catch(error){output.textContent=error.message;}finally{judge?.stop();running=false;document.getElementById('bulkRun').disabled=false;document.getElementById('bulkStop').hidden=true;}
 };
 return {accountChanged(){stopped=true;judge?.stop();},setVisible(visible){panel.hidden=!visible;}};
}

